@SuppressWarnings("unchecked")
@Test
public void testgroupTableDataChunksIntoSplits() {
    List<OraOopOracleDataChunk> dataChunks = new ArrayList<OraOopOracleDataChunk>();
    int startBlockNumber = 1;
    for (int idx = 0; idx < 241; idx++) {
        OraOopOracleDataChunk dataChunk = new OraOopOracleDataChunkExtent("23480", 666, 1, startBlockNumber, startBlockNumber + 8);
        startBlockNumber += 8;
        dataChunks.add(dataChunk);
    }
    @SuppressWarnings("rawtypes")
    Exposer e = new Exposer();
    // Prevent setJdbcFetchSize() from logging information about the fetch-size
    // changing. Otherwise, the junit output will be polluted with messages
    // about
    // things that aren't actually a problem...
    boolean logIsBeingCached = Exposer.LOG.getCacheLogEntries();
    Exposer.LOG.setCacheLogEntries(true);
    List<InputSplit> splits = e.groupTableDataChunksIntoSplits(dataChunks, 32, OraOopOracleBlockToSplitAllocationMethod.SEQUENTIAL);
    Exposer.LOG.setCacheLogEntries(logIsBeingCached);
    int highestNumberOfDataChunksAllocatedToASplit = 0;
    int lowestNumberOfDataChunksAllocatedToASplit = Integer.MAX_VALUE;
    // Check that all splits have data-chunks assigned to them...
    for (InputSplit split : splits) {
        int dataChunksAllocatedToThisSplit = ((OraOopDBInputSplit) split).getNumberOfDataChunks();
        highestNumberOfDataChunksAllocatedToASplit = Math.max(highestNumberOfDataChunksAllocatedToASplit, dataChunksAllocatedToThisSplit);
        lowestNumberOfDataChunksAllocatedToASplit = Math.min(lowestNumberOfDataChunksAllocatedToASplit, dataChunksAllocatedToThisSplit);
    }
    if (lowestNumberOfDataChunksAllocatedToASplit == 0) {
        Assert.fail("There is a split that has not had any " + "data-chunks allocated to it.");
    }
    // Check that the split with the least data-chunks has at least
    // 75% of the number of data-chunks of the split with the most
    // data-chunks...
    double minExpectedWorkloadRatio = 0.75;
    double actualWorkloadRatio = (double) lowestNumberOfDataChunksAllocatedToASplit / highestNumberOfDataChunksAllocatedToASplit;
    if (actualWorkloadRatio < minExpectedWorkloadRatio) {
        Assert.fail(String.format("There is too much difference in the amount of work assigned " + "to the 'smallest' split and the 'largest' split. " + "The split with the least work should have at least %s " + "of the workload of the 'largest' split, but it actually " + "only has %s of the workload of the 'largest' split.", minExpectedWorkloadRatio, actualWorkloadRatio));
    }
}

@Test
public void testParseJdbcOracleThinConnectionString() {
    OraOopUtilities.JdbcOracleThinConnection actual;
    // Null JDBC URL...
    try {
        actual = new OraOopJdbcUrl(null).parseJdbcOracleThinConnectionString();
        Assert.fail("An IllegalArgumentException should be been thrown.");
    } catch (IllegalArgumentException ex) {
        /* This is what we want to happen. */
    } catch (JdbcOracleThinConnectionParsingError ex) {
        Assert.fail("An IllegalArgumentException should be been thrown.");
    }
    // Empty JDBC URL...
    try {
        actual = new OraOopJdbcUrl("").parseJdbcOracleThinConnectionString();
        Assert.fail("An IllegalArgumentException should be been thrown.");
    } catch (IllegalArgumentException ex) {
        /* This is what we want to happen. */
    } catch (JdbcOracleThinConnectionParsingError ex) {
        Assert.fail("An IllegalArgumentException should be been thrown.");
    }
    // Incorrect number of fragments in the URL...
    try {
        actual = new OraOopJdbcUrl("jdbc:oracle:oci8:@dbname.domain").parseJdbcOracleThinConnectionString();
        Assert.fail("A JdbcOracleThinConnectionParsingError should be been thrown.");
    } catch (JdbcOracleThinConnectionParsingError ex) {
        // This is what we want to happen.
        assertTrue("An exception should be thown that tells us there's an incorrect " + "number of fragments in the JDBC URL.", ex.getMessage().toLowerCase().contains("the oracle \"thin\" jdbc driver is not being used."));
    }
    // Incorrect driver-type (i.e. not using the "thin" driver)...
    try {
        actual = new OraOopJdbcUrl("jdbc:oracle:loremipsum:@hostname.domain.com.au:port1521:dbsid").parseJdbcOracleThinConnectionString();
        Assert.fail("A JdbcOracleThinConnectionParsingError should be been thrown.");
    } catch (JdbcOracleThinConnectionParsingError ex) {
        // This is what we want to happen.
        assertTrue("An exception should be thown that refers to the fact that the thin " + "JDBC driver is not being used.", ex.getMessage().toLowerCase().contains("oracle \"thin\" jdbc driver is not being used"));
        assertTrue("An exception should be thown that tells us which JDBC driver " + "was specified.", ex.getMessage().toLowerCase().contains("loremipsum"));
    }
    // Invalid JDBC URL (unparsable port number)...
    try {
        actual = new OraOopJdbcUrl("jdbc:oracle:thin:@hostname.domain.com.au:port1521:dbsid").parseJdbcOracleThinConnectionString();
        Assert.fail("An JdbcOracleThinConnectionParsingError should be been thrown.");
    } catch (JdbcOracleThinConnectionParsingError ex) {
        assertTrue("The invalid port number should be included in the exception message.", ex.getMessage().toLowerCase().contains("port1521"));
    }
    // Invalid JDBC URL (negative port number)...
    try {
        actual = new OraOopJdbcUrl("jdbc:oracle:thin:@hostname.domain.com.au:-1521:dbsid").parseJdbcOracleThinConnectionString();
        Assert.fail("An JdbcOracleThinConnectionParsingError should be been thrown.");
    } catch (JdbcOracleThinConnectionParsingError ex) {
        assertTrue("The invalid port number should be included in the exception message.", ex.getMessage().toLowerCase().contains("-1521"));
    }
    // Valid JDBC URL...
    try {
        actual = new OraOopJdbcUrl("JDBC:Oracle:tHiN:@hostname.domain.com.au:1521:dbsid").parseJdbcOracleThinConnectionString();
        Assert.assertEquals("hostname.domain.com.au", actual.getHost());
        Assert.assertEquals(1521, actual.getPort());
        Assert.assertEquals("dbsid", actual.getSid());
    } catch (JdbcOracleThinConnectionParsingError ex) {
        Assert.fail(ex.getMessage());
    }
    // Valid JDBC URL...
    try {
        actual = new OraOopJdbcUrl(" JDBC : Oracle : tHiN : @hostname.domain.com.au : 1529 : dbsid").parseJdbcOracleThinConnectionString();
        Assert.assertEquals("hostname.domain.com.au", actual.getHost());
        Assert.assertEquals(1529, actual.getPort());
        Assert.assertEquals("dbsid", actual.getSid());
    } catch (JdbcOracleThinConnectionParsingError ex) {
        Assert.fail(ex.getMessage());
    }
    // Valid (sid-based) JDBC URL with parameters...
    try {
        actual = new OraOopJdbcUrl("jdbc:oracle:thin:@hostname:1521:dbsid?param1=loremipsum").parseJdbcOracleThinConnectionString();
        Assert.assertEquals("hostname", actual.getHost());
        Assert.assertEquals(1521, actual.getPort());
        Assert.assertEquals("dbsid", actual.getSid());
        Assert.assertEquals(null, actual.getService());
    } catch (JdbcOracleThinConnectionParsingError ex) {
        Assert.fail(ex.getMessage());
    }
    // Valid (service-based) JDBC URL...
    try {
        actual = new OraOopJdbcUrl("jdbc:oracle:thin:@hostname:1521/dbservice.dbdomain").parseJdbcOracleThinConnectionString();
        Assert.assertEquals("hostname", actual.getHost());
        Assert.assertEquals(1521, actual.getPort());
        Assert.assertEquals(null, actual.getSid());
        Assert.assertEquals("dbservice.dbdomain", actual.getService());
    } catch (JdbcOracleThinConnectionParsingError ex) {
        Assert.fail(ex.getMessage());
    }
    // Valid (service-based) JDBC URL with slashes...
    try {
        actual = new OraOopJdbcUrl("jdbc:oracle:thin:@//hostname:1521/dbservice.dbdomain").parseJdbcOracleThinConnectionString();
        Assert.assertEquals("hostname", actual.getHost());
        Assert.assertEquals(1521, actual.getPort());
        Assert.assertEquals(null, actual.getSid());
        Assert.assertEquals("dbservice.dbdomain", actual.getService());
    } catch (JdbcOracleThinConnectionParsingError ex) {
        Assert.fail(ex.getMessage());
    }
    // Valid (service-based) JDBC URL with parameters...
    try {
        actual = new OraOopJdbcUrl("jdbc:oracle:thin:@hostname:1521/dbservice.dbdomain?param1=loremipsum").parseJdbcOracleThinConnectionString();
        Assert.assertEquals("hostname", actual.getHost());
        Assert.assertEquals(1521, actual.getPort());
        Assert.assertEquals(null, actual.getSid());
        Assert.assertEquals("dbservice.dbdomain", actual.getService());
    } catch (JdbcOracleThinConnectionParsingError ex) {
        Assert.fail(ex.getMessage());
    }
    // Valid (service-based) JDBC URL with slashes and parameters...
    try {
        actual = new OraOopJdbcUrl("jdbc:oracle:thin:@//hostname:1521/dbservice.dbdomain?param1=loremipsum").parseJdbcOracleThinConnectionString();
        Assert.assertEquals("hostname", actual.getHost());
        Assert.assertEquals(1521, actual.getPort());
        Assert.assertEquals(null, actual.getSid());
        Assert.assertEquals("dbservice.dbdomain", actual.getService());
    } catch (JdbcOracleThinConnectionParsingError ex) {
        Assert.fail(ex.getMessage());
    }
}

