    }
    assertNotNull(cls);
    Constructor c = cls.getConstructor(Configuration.class, TaskAttemptID.class);
    context = (TaskAttemptContext) c.newInstance(conf, new TaskAttemptID());
    SqlServerUpsertOutputFormat outputFormat = new SqlServerUpsertOutputFormat();
    SqlServerUpsertRecordWriter recordWriter = outputFormat.new SqlServerUpsertRecordWriter(context);
    assertEquals("SET IDENTITY_INSERT #myTable ON " + "MERGE INTO #myTable AS _target USING ( VALUES ( ?, ?, ? ) )" + " AS _source ( FirstColumn, SecondColumn, ThirdColumn ) ON " + "_source.FirstColumn = _target.FirstColumn" + "  WHEN MATCHED THEN UPDATE SET _target.SecondColumn = " + "_source.SecondColumn, _target.ThirdColumn = _source.ThirdColumn" + "  WHEN NOT MATCHED THEN INSERT ( FirstColumn, SecondColumn, " + " ThirdColumn ) VALUES " + "( _source.FirstColumn, _source.SecondColumn, _source.ThirdColumn ) " + "OPTION (NOLOCK);", recordWriter.getUpdateStatement());
}

